#!/bin/bash
set -e
mkdir -p /logs/verifier

cat << 'TEST_EOF' > /tmp/test_final_state.py
import csv
import itertools
import json
import math
import os
import sqlite3

import numpy as np
import pandas as pd
import pytest

DB_PATH = "/home/user/sensor_data.db"
JSON_PATH = "/home/user/correlated_sensors.json"
RAW_DATA_DIR = "/home/user/raw_data"


def reference_clean_data():
    """Recreate the immutable input generated by setup, independently of agent changes."""
    np.random.seed(101)
    timestamps = pd.date_range(start="2023-01-01", periods=1000, freq="min").astype(str)
    sensors = [f"S_{i}" for i in range(10)]
    values = {sensor: np.random.normal(0, 1, 1000) for sensor in sensors}
    values["S_7"] = 0.9 * values["S_2"] + 0.1 * np.random.normal(0, 1, 1000)
    values["S_9"] = -0.85 * values["S_4"] + 0.15 * np.random.normal(0, 1, 1000)

    frame = pd.DataFrame(values)
    frame["timestamp"] = timestamps
    melted = frame.melt(id_vars=["timestamp"], var_name="sensor_id", value_name="value")
    missing = np.random.rand(len(melted)) < 0.01
    melted.loc[missing, "value"] = np.nan
    melted = melted.sample(frac=1, random_state=101).reset_index(drop=True)
    return melted.dropna(subset=["value"]).loc[lambda d: d["sensor_id"] != "", ["timestamp", "sensor_id", "value"]]


def read_clean_csv_rows():
    rows = []
    for file_name in sorted(os.listdir(RAW_DATA_DIR)):
        if not file_name.endswith(".csv"):
            continue
        with open(os.path.join(RAW_DATA_DIR, file_name), newline="") as handle:
            for row in csv.DictReader(handle):
                sensor_id = row.get("sensor_id", "")
                value_text = row.get("value", "")
                if not sensor_id or not value_text:
                    continue
                value = float(value_text)
                if math.isnan(value):
                    continue
                rows.append((row.get("timestamp"), sensor_id, value))
    return rows


def assert_same_readings(expected_rows, actual_rows):
    assert len(actual_rows) == len(expected_rows), (
        f"Expected {len(expected_rows)} cleaned readings, found {len(actual_rows)}"
    )

    expected = {}
    for timestamp, sensor_id, value in expected_rows:
        key = (timestamp, sensor_id)
        assert key not in expected, f"Duplicate key in expected input: {key}"
        expected[key] = float(value)

    actual = {}
    for timestamp, sensor_id, value in actual_rows:
        key = (timestamp, sensor_id)
        assert key not in actual, f"Duplicate reading in database for {key}"
        assert isinstance(timestamp, str), f"Timestamp for {key} is not stored as text"
        assert isinstance(sensor_id, str), f"Sensor ID for {key} is not stored as text"
        assert isinstance(value, (int, float)) and not isinstance(value, bool), f"Value for {key} is not numeric"
        assert math.isfinite(float(value)), f"Value for {key} is not finite"
        actual[key] = float(value)

    assert set(actual) == set(expected), "Database timestamp/sensor_id pairs do not match the cleaned input"
    for key, expected_value in expected.items():
        assert math.isclose(actual[key], expected_value, rel_tol=1e-12, abs_tol=1e-12), (
            f"Incorrect value for {key}: expected {expected_value}, found {actual[key]}"
        )


def expected_report():
    clean = reference_clean_data()
    pivoted = clean.pivot(index="timestamp", columns="sensor_id", values="value")
    sensors = sorted(pivoted.columns.tolist())
    pairs = list(itertools.combinations(sensors, 2))
    distributions = {pair: [] for pair in pairs}

    # The required seed is set immediately before the 500-iteration bootstrap loop.
    np.random.seed(42)
    row_count = len(pivoted)
    for _ in range(500):
        indices = np.random.choice(row_count, size=row_count, replace=True)
        sample = pivoted.iloc[indices]
        corr = sample.corr(method="pearson")
        for sensor_a, sensor_b in pairs:
            distributions[(sensor_a, sensor_b)].append(float(corr.loc[sensor_a, sensor_b]))

    report = []
    for sensor_a, sensor_b in pairs:
        distribution = np.asarray(distributions[(sensor_a, sensor_b)], dtype=float)
        mean_corr = float(np.mean(distribution))
        if abs(mean_corr) > 0.75:
            report.append({
                "sensor_a": sensor_a,
                "sensor_b": sensor_b,
                "mean_corr": float(np.round(mean_corr, 3)),
                "ci_lower": float(np.round(np.percentile(distribution, 2.5), 3)),
                "ci_upper": float(np.round(np.percentile(distribution, 97.5), 3)),
            })
    return report


def test_db_exists_and_schema():
    assert os.path.exists(DB_PATH), f"Database file not found at {DB_PATH}"
    conn = sqlite3.connect(DB_PATH)
    cursor = conn.cursor()
    cursor.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='readings';")
    assert cursor.fetchone() is not None, "Table 'readings' does not exist in the database."

    cursor.execute("PRAGMA table_info(readings);")
    columns = {row[1]: row[2].upper() for row in cursor.fetchall()}
    expected_columns = {"timestamp": "TEXT", "sensor_id": "TEXT", "value": "REAL"}
    for column, expected_type in expected_columns.items():
        assert column in columns, f"Column '{column}' is missing from the 'readings' table."
        assert expected_type in columns[column], (
            f"Column '{column}' has incorrect type. Expected {expected_type}, got {columns[column]}."
        )
    conn.close()


def test_db_row_count():
    assert os.path.exists(RAW_DATA_DIR), f"Raw data directory not found at {RAW_DATA_DIR}"
    expected_count = len(read_clean_csv_rows())
    assert os.path.exists(DB_PATH), f"Database file not found at {DB_PATH}"
    conn = sqlite3.connect(DB_PATH)
    actual_count = conn.execute("SELECT COUNT(*) FROM readings").fetchone()[0]
    conn.close()
    assert actual_count == expected_count, (
        f"Expected {expected_count} rows in the database, but found {actual_count}."
    )


def test_database_matches_csv_and_original_input():
    csv_rows = read_clean_csv_rows()
    generated = reference_clean_data()
    reference_rows = list(generated.itertuples(index=False, name=None))

    # Ensure mutable input files still represent the setup data, then compare every DB field to them.
    assert_same_readings(reference_rows, csv_rows)
    conn = sqlite3.connect(DB_PATH)
    db_rows = conn.execute("SELECT timestamp, sensor_id, value FROM readings").fetchall()
    conn.close()
    assert_same_readings(csv_rows, db_rows)


def test_json_exists_and_valid():
    assert os.path.exists(JSON_PATH), f"JSON report not found at {JSON_PATH}"
    with open(JSON_PATH) as handle:
        try:
            data = json.load(handle)
        except json.JSONDecodeError:
            pytest.fail(f"File at {JSON_PATH} is not valid JSON.")
    assert isinstance(data, list), "JSON root must be a list."


def test_json_structure_and_content():
    with open(JSON_PATH) as handle:
        data = json.load(handle)

    expected_keys = {"sensor_a", "sensor_b", "mean_corr", "ci_lower", "ci_upper"}
    for item in data:
        assert isinstance(item, dict), "Every JSON list item must be an object."
        assert set(item.keys()) == expected_keys, (
            f"JSON object has incorrect keys. Expected {expected_keys}, got {set(item.keys())}"
        )
        assert isinstance(item["sensor_a"], str) and isinstance(item["sensor_b"], str)
        assert item["sensor_a"] < item["sensor_b"], (
            f"sensor_a ('{item['sensor_a']}') is not lexicographically smaller than sensor_b ('{item['sensor_b']}')."
        )
        for key in ["mean_corr", "ci_lower", "ci_upper"]:
            value = item[key]
            assert isinstance(value, (int, float)) and not isinstance(value, bool), f"{key} must be numeric"
            assert math.isfinite(float(value)), f"{key} must be finite"
            val_str = str(value)
            if "." in val_str:
                assert len(val_str.split(".")[1]) <= 3, f"Value for {key} ({value}) is not rounded to 3 decimal places."

    pairs = [(item["sensor_a"], item["sensor_b"]) for item in data]
    assert pairs == sorted(pairs), "JSON list is not sorted by sensor_a, then sensor_b."
    expected_pairs = {("S_2", "S_7"), ("S_4", "S_9")}
    assert set(pairs) == expected_pairs, f"Expected highly correlated pairs {expected_pairs}, but got {set(pairs)}."

    for item in data:
        if (item["sensor_a"], item["sensor_b"]) == ("S_2", "S_7"):
            assert item["mean_corr"] > 0.9, f"Expected strong positive correlation, got {item['mean_corr']}"
        elif (item["sensor_a"], item["sensor_b"]) == ("S_4", "S_9"):
            assert item["mean_corr"] < -0.9, f"Expected strong negative correlation, got {item['mean_corr']}"

    expected = expected_report()
    assert len(data) == len(expected)
    for actual_item, expected_item in zip(data, expected):
        assert actual_item["sensor_a"] == expected_item["sensor_a"]
        assert actual_item["sensor_b"] == expected_item["sensor_b"]
        for key in ["mean_corr", "ci_lower", "ci_upper"]:
            assert math.isclose(float(actual_item[key]), expected_item[key], rel_tol=0, abs_tol=1e-12), (
                f"Incorrect bootstrap {key} for {(actual_item['sensor_a'], actual_item['sensor_b'])}: "
                f"expected {expected_item[key]}, got {actual_item[key]}"
            )
TEST_EOF

if python3 -m pytest /tmp/test_final_state.py -x --tb=short 2>&1; then
    echo "1" > /logs/verifier/reward.txt
else
    echo "0" > /logs/verifier/reward.txt
fi
